struct price_ctx { const struct order *o; double qty, base, discount; };
static void ctx_discount(struct price_ctx *c) { c->discount = c->qty > 100 ? .05 : 0; }
static double ctx_compute(struct price_ctx *c) { ctx_discount(c); return c->base * c->qty * (1 - c->discount); }

double order_price(const struct order *o) {
    struct price_ctx c = { .o = o, .qty = o->qty, .base = order_base(o) };
    return ctx_compute(&c);
}
